  &lt;span class="ar-algorithm-label"&gt;算法步骤&lt;/span&gt;
  &lt;ol class="ar-intro-steps"&gt;
    &lt;li&gt;生成 \(Y\sim g\)&lt;/li&gt;
    &lt;li&gt;生成 \(U\sim\operatorname{Uniform}(0,1)\)&lt;/li&gt;
    &lt;li&gt;若 \(U\leq \dfrac{f(Y)}{c\,g(Y)}\)，接受 \(Y\)；否则拒绝并重新试验&lt;/li&gt;
  &lt;/ol&gt;
&lt;/div&gt;


&lt;section class="ar-controls" aria-label="实验参数"&gt;
  &lt;div class="ar-distribution-picker"&gt;
    &lt;fieldset class="ar-radio-group"&gt;
      &lt;legend&gt;目标分布 \(f\)&lt;/legend&gt;
      &lt;label class="ar-radio-option"&gt;&lt;input type="radio" name="ar-target" value="beta" checked&gt;&lt;span&gt;&lt;strong&gt;\(\operatorname{Beta}(4,3)\)&lt;/strong&gt;&lt;small&gt;定义域：\([0,1]\)&lt;/small&gt;&lt;/span&gt;&lt;/label&gt;
      &lt;label class="ar-radio-option"&gt;&lt;input type="radio" name="ar-target" value="gamma"&gt;&lt;span&gt;&lt;strong&gt;\(\operatorname{Gamma}(3/2,1)\)&lt;/strong&gt;&lt;small&gt;定义域：\((0,\infty)\)&lt;/small&gt;&lt;/span&gt;&lt;/label&gt;
    &lt;/fieldset&gt;
    &lt;fieldset class="ar-radio-group"&gt;
      &lt;legend&gt;提议分布 \(g\)&lt;/legend&gt;
      &lt;label class="ar-radio-option"&gt;&lt;input type="radio" name="ar-proposal" value="uniform1" checked&gt;&lt;span&gt;&lt;strong&gt;\(\operatorname{Uniform}(0,1)\)&lt;/strong&gt;&lt;small&gt;定义域：\([0,1]\)&lt;/small&gt;&lt;/span&gt;&lt;/label&gt;
      &lt;label class="ar-radio-option"&gt;&lt;input type="radio" name="ar-proposal" value="uniform2"&gt;&lt;span&gt;&lt;strong&gt;\(\operatorname{Uniform}(0,2)\)&lt;/strong&gt;&lt;small&gt;定义域：\([0,2]\)&lt;/small&gt;&lt;/span&gt;&lt;/label&gt;
      &lt;label class="ar-radio-option"&gt;&lt;input type="radio" name="ar-proposal" value="exponential"&gt;&lt;span&gt;&lt;strong&gt;\(\operatorname{Exp}(2/3)\)&lt;/strong&gt;&lt;small&gt;定义域：\([0,\infty)\)&lt;/small&gt;&lt;/span&gt;&lt;/label&gt;
    &lt;/fieldset&gt;
  &lt;/div&gt;

  &lt;div class="ar-formula" id="ar-formula" aria-live="polite"&gt;&lt;/div&gt;

  &lt;div class="ar-control-group"&gt;
    &lt;div class="ar-label-row"&gt;
      &lt;label for="ar-c"&gt;包络系数 \(c\)&lt;/label&gt;
      &lt;output id="ar-c-value"&gt;&lt;/output&gt;
    &lt;/div&gt;
    &lt;input id="ar-c" type="range" step="0.01"&gt;
    &lt;div class="ar-range-hint"&gt;&lt;span id="ar-c-min"&gt;&lt;/span&gt;&lt;span id="ar-c-max"&gt;&lt;/span&gt;&lt;/div&gt;
    &lt;p class="ar-help"&gt;增大 \(c\) 会降低接受率。只有当 \(g\) 完整覆盖 \(f\) 的定义域时，理论接受率才是 \(1/c\)。&lt;/p&gt;
  &lt;/div&gt;

  &lt;div class="ar-control-group"&gt;
    &lt;div class="ar-label-row"&gt;
      &lt;label for="ar-n"&gt;希望接受的样本数&lt;/label&gt;
      &lt;output id="ar-n-value"&gt;500&lt;/output&gt;
    &lt;/div&gt;
    &lt;input id="ar-n" type="range" min="50" max="2000" step="50" value="500"&gt;
    &lt;div class="ar-range-hint"&gt;&lt;span&gt;50&lt;/span&gt;&lt;span&gt;2000&lt;/span&gt;&lt;/div&gt;
  &lt;/div&gt;

  &lt;div class="ar-actions"&gt;
    &lt;button type="button" class="ar-primary" id="ar-run"&gt;运行实验&lt;/button&gt;
    &lt;button type="button" class="ar-secondary" id="ar-step"&gt;单步试验&lt;/button&gt;
    &lt;button type="button" class="ar-ghost" id="ar-reset"&gt;重置&lt;/button&gt;
  &lt;/div&gt;

&lt;/section&gt;

&lt;div class="ar-results"&gt;
  &lt;section class="ar-stat-grid" aria-label="实验结果摘要"&gt;
    &lt;div class="ar-stat"&gt;&lt;span&gt;已接受&lt;/span&gt;&lt;strong id="ar-accepted"&gt;0&lt;/strong&gt;&lt;/div&gt;
    &lt;div class="ar-stat"&gt;&lt;span&gt;总试验数&lt;/span&gt;&lt;strong id="ar-trials"&gt;0&lt;/strong&gt;&lt;/div&gt;
    &lt;div class="ar-stat"&gt;&lt;span&gt;经验接受率&lt;/span&gt;&lt;strong id="ar-rate"&gt;—&lt;/strong&gt;&lt;/div&gt;
    &lt;div class="ar-stat ar-stat-theory"&gt;&lt;span&gt;理论接受率&lt;/span&gt;&lt;strong id="ar-theory"&gt;—&lt;/strong&gt;&lt;/div&gt;
  &lt;/section&gt;

  &lt;section class="ar-panel ar-envelope-panel"&gt;
    &lt;div class="ar-panel-heading"&gt;
      &lt;div&gt;
        &lt;h2&gt;候选点落在哪里？&lt;/h2&gt;
        &lt;p&gt;曲线下方的候选点被接受；曲线与包络之间的点被拒绝。&lt;/p&gt;
      &lt;/div&gt;
      &lt;div class="ar-legend" aria-label="图例"&gt;
        &lt;span&gt;&lt;i class="ar-dot accepted"&gt;&lt;/i&gt;接受&lt;/span&gt;
        &lt;span&gt;&lt;i class="ar-dot rejected"&gt;&lt;/i&gt;拒绝&lt;/span&gt;
      &lt;/div&gt;
    &lt;/div&gt;
    &lt;div class="ar-chart-frame"&gt;
      &lt;span class="ar-axis-label ar-y-axis"&gt;抽样高度 \(Z=U\cdot c\,g(Y)\)&lt;/span&gt;
      &lt;canvas id="ar-envelope" role="img" aria-label="横轴为候选值Y，纵轴为抽样高度Z；展示目标密度、包络曲线与候选点"&gt;&lt;/canvas&gt;
      &lt;span class="ar-axis-label ar-x-axis"&gt;候选值 \(Y\)&lt;/span&gt;
    &lt;/div&gt;
  &lt;/section&gt;

  &lt;section class="ar-panel"&gt;
    &lt;div class="ar-panel-heading"&gt;
      &lt;div&gt;
        &lt;h2&gt;接受的样本像目标分布吗？&lt;/h2&gt;
        &lt;p&gt;柱形是接受样本的经验密度，蓝线是目标密度 \(f(x)\)。&lt;/p&gt;
      &lt;/div&gt;
      &lt;span class="ar-status" id="ar-status" aria-live="polite"&gt;等待实验&lt;/span&gt;
    &lt;/div&gt;
    &lt;div class="ar-chart-frame"&gt;
      &lt;span class="ar-axis-label ar-y-axis"&gt;经验密度&lt;/span&gt;
      &lt;canvas id="ar-histogram" role="img" aria-label="横轴为接受样本X，纵轴为经验密度；展示接受样本直方图与目标密度"&gt;&lt;/canvas&gt;
      &lt;span class="ar-axis-label ar-x-axis"&gt;接受样本 \(X\)&lt;/span&gt;
    &lt;/div&gt;
  &lt;/section&gt;
&lt;/div&gt;

